    from collections import deque

    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with Dijkstra's algorithm
    dist = [-1] * n
    dist[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v, w in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + w
                queue.append(v)
            else:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    queue.append(v)

    return dist[t] if dist[t] != -1 else -1

