def solve(n, edges, s, t):
    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with Dijkstra's algorithm for shortest path
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)
        if visited[u]:
            continue
        visited[u] = True
        if u == t:
            break
        for v, w in adj[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))

    return dist[t] if dist[t] != float('inf') else -1

